 'use strict';
const $=id=>document.getElementById(id), K='aktien-cockpit-4-1', CK='aktien-cockpit-capital-4-4', TK='aktien-cockpit-trades-4-5';
let positions=[],sales=[],settings={goal:658,tax:26.375,lossStart:0},tradePosition=null,sellPosition=null;
const base=[['isin','ISIN (optional)','text','Eindeutige internationale Wertpapierkennung für den Bestandsabgleich'],['wkn','WKN (optional)','text','Deutsche Wertpapierkennnummer'],['name','Aktienname','text','Unternehmen oder Aktie'],['price','Aktueller Kurs (€)','number','Aktueller Kurs in Euro'],['pe','KGV','number','Kurs-Gewinn-Verhältnis, auch negativ möglich'],['sma50','SMA 50 (€)','number','Einfacher Durchschnitt der letzten 50 Handelstage'],['sma200','SMA 200 (€)','number','Einfacher Durchschnitt der letzten 200 Handelstage'],['rsi','RSI (14)','number','Unter 30 häufig überverkauft, über 70 häufig überkauft']];
const growth=[['yearOld','Vorjahr','number','Vorletztes abgeschlossenes Geschäftsjahr'],['yearNew','Letztes Geschäftsjahr','number','Letztes abgeschlossenes Geschäftsjahr'],['salesOld','Umsatz Vorjahr (Mio. €)','number','Jahresumsatz'],['salesNew','Umsatz aktuell (Mio. €)','number','Jahresumsatz'],['profitOld','Nettoergebnis Vorjahr (Mio. €)','number','Verluste negativ eingeben'],['profitNew','Nettoergebnis aktuell (Mio. €)','number','Verluste negativ eingeben']];
const extra=[['ev','EV/EBITDA','number','Unternehmenswert geteilt durch EBITDA'],['margin','Operative Marge TTM (%)','number','Operative Marge'],['debtRatio','Verschuldung/Eigenkapital (%)','number','Schulden im Verhältnis zum Eigenkapital'],['fcf','Levered Free Cashflow (Mio. €)','number','Nach Schuldendienst verfügbarer Cashflow'],['fcfYear','FCF-Geschäftsjahr','number','Zugehöriges Geschäftsjahr'],['roe','ROE (%)','number','Eigenkapitalrendite'],['netDebt','Nettoverschuldung (Mio. €)','number','Negative Werte bedeuten Nettoliquidität'],['netDebtDate','Nettoverschuldung Stichtag','text','Datum'],['target','Ø Analysten-Kursziel (€)','number','Unverbindliches Kursziel'],['targetDate','Kursziel-Stand','text','Datum']];
const personal=[['quality','Geschäftsmodell','select','Subjektive Einschätzung'],['outlook','Zukunftsaussichten','select','Subjektive Einschätzung'],['risk','Anlagerisiko','select','Geringes, mittleres oder hohes Risiko']];
const trade=[['buyPrice','Einstiegskurs (€)','number','Wenn leer, gilt der aktuelle Kurs'],['budget','Budget (€)','number','Inklusive Kaufgebühr'],['shares','Stückzahl','number','Ganze Aktien, hat Vorrang vor Budget'],['buyFee','Kaufgebühr (€)','number','Standard 1 €'],['sellFee','Verkaufsgebühr (€)','number','Standard 1 €'],['taxRate','Steuer gesamt (%)','number','Typisch 26,375 % ohne Kirchensteuer'],['allowance','Verfügbarer Freibetrag (€)','number','Nur noch verfügbarer Betrag'],['customPct','Eigene Kursänderung (%)','number','Auch negative Prozentwerte']];
const stops=[['stopPct','Stop-Loss Abstand (%)','number','Abstand vom Einstieg'],['stopEuro','Stop-Loss Abstand (€ je Aktie)','number','Hat Vorrang vor Prozent'],['highest','Höchster Kurs (€)','number','Für Trailing-Stop'],['trailPct','Trailing-Abstand (%)','number','Vom bisherigen Höchstkurs'],['trailEuro','Trailing-Abstand (€ je Aktie)','number','Hat Vorrang vor Prozent'],['desiredNet','Nettogewinn absichern (€)','number','Gewünschter Gesamtgewinn nach Gebühren und geschätzten Steuern; negative Werte möglich']];
const all=[...base,...growth,...extra,...personal,...trade,...stops];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function parse(v){if(v==null||String(v).trim()==='')return null;let s=String(v).trim().replace(/\s/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');const n=Number(s);return Number.isFinite(n)?n:null}
const fmt=(n,d=2)=>n==null||!Number.isFinite(n)?'–':n.toLocaleString('de-DE',{minimumFractionDigits:d,maximumFractionDigits:d});
const sign=(n,d=2)=>n==null?'–':(n>0?'+':'')+fmt(n,d);
const money=n=>fmt(n)+' €';
function fields(id,defs){$(id).innerHTML=defs.map(([key,label,type,tip])=>`<div class="field"><label for="${key}">${esc(label)} <button class="info" type="button" data-tip="${esc(tip)}" data-title="${esc(label)}">i</button></label>${type==='select'?`<select id="${key}">${key==='risk'?'<option value="">Nicht bewertet</option><option value="good">Geringes Risiko</option><option value="neutral">Mittleres Risiko</option><option value="bad">Hohes Risiko</option>':'<option value="">Nicht bewertet</option><option value="good">Gut</option><option value="neutral">Mittel</option><option value="bad">Schwach</option>'}</select>`:`<input id="${key}" type="${type==='number'?'text':'text'}" ${type==='number'?'inputmode="text"':''} autocomplete="off">${type==="number"?`<button type="button" class="minus-btn" data-minus-for="${key}" aria-label="Vorzeichen wechseln">±</button>`:""}`}</div>`).join('')}
for(const [id,defs] of [['baseFields',base],['growthFields',growth],['extraFields',extra],['personalFields',personal],['tradeFields',trade],['stopFields',stops]])fields(id,defs);
let entries=[],bookings=[],actualTotal=null,editId=null,bookEdit=null;
function get(){const d={};for(const [id,,type] of all)d[id]=type==='number'?parse($(id).value):$(id).value.trim();d.notes=$('notes').value;d.riskMax=parse($('riskMax').value)??30;return d}
function set(d){for(const [id] of all)$(id).value=d[id]??'';$('notes').value=d.notes??'';$('riskMax').value=d.riskMax??30;render()}
function metric(k,v,cls=''){return `<div class="metric"><small>${esc(k)}</small><strong class="${cls}">${esc(v)}</strong></div>`}
function growthPct(a,b){if(a==null||b==null)return null;if(a<0&&b>=0)return 'Turnaround';if(a>=0&&b<0)return 'Verlustphase';if(a<=0||b<0)return 'Nicht vergleichbar';return (b-a)/Math.abs(a)*100}
function evaluate(d){let tech=[],fund=[],pers=[],reasons=[];
if(d.price>0&&d.sma50>0){const p=(d.price/d.sma50-1)*100;tech.push(p>=0?(p>12?.35:.8):p>=-5?.55:.2);reasons.push(`SMA 50: ${sign(d.price-d.sma50)} € (${sign(p)} %) Abstand`)}
if(d.price>0&&d.sma200>0){const p=(d.price/d.sma200-1)*100;tech.push(p>=0?.85:.25);reasons.push(`SMA 200: ${sign(d.price-d.sma200)} € (${sign(p)} %) Abstand`)}
if(d.rsi!=null&&d.rsi>=0&&d.rsi<=100){tech.push(d.rsi>75?.2:d.rsi>=65?.45:d.rsi>=40?.75:d.rsi>=30?.6:.35);reasons.push(`RSI ${fmt(d.rsi,1)}`)}
if(d.pe!=null)fund.push(d.pe<=0?.15:d.pe<8?.7:d.pe<20?.8:d.pe<35?.55:.25);
if(d.ev!=null)fund.push(d.ev<=0?.15:d.ev<6?.75:d.ev<12?.65:.35);
if(d.margin!=null)fund.push(d.margin<0?.15:d.margin<5?.4:d.margin<15?.7:.85);
if(d.debtRatio!=null)fund.push(d.debtRatio<0?.5:d.debtRatio<60?.8:d.debtRatio<150?.55:.3);
if(d.fcf!=null)fund.push(d.fcf>0?.7:d.fcf<0?.25:.5);
if(d.roe!=null)fund.push(d.roe<0?.15:d.roe<8?.45:d.roe<25?.8:.65);
if(d.netDebt!=null)fund.push(d.netDebt<0?.8:.5);
const sg=growthPct(d.salesOld,d.salesNew),pg=growthPct(d.profitOld,d.profitNew);
for(const g of [sg,pg])if(typeof g==='number')fund.push(g<0?.25:g<5?.55:g<20?.75:.85);
if(pg==='Turnaround')fund.push(.65);if(pg==='Verlustphase')fund.push(.1);
for(const k of ['quality','outlook','risk'])if(d[k])pers.push(({good:.85,neutral:.5,bad:.2})[d[k]]??.5);
const groups=[[tech,.45],[fund,.4],[pers,.15]].filter(([a])=>a.length);
const score=groups.length?Math.round(100*groups.reduce((s,[a,w])=>s+w*a.reduce((x,y)=>x+y,0)/a.length,0)/groups.reduce((s,[a,w])=>s+w,0)):null;
const covered=[...base.slice(1),...growth.slice(2),...extra.filter(x=>!['fcfYear','netDebtDate','targetDate'].includes(x[0]))].filter(([k])=>d[k]!=null&&d[k]!=='').length;
return {score,covered,reliability:covered>=10?'höher':covered>=6?'mittel':'gering',sg,pg,reasons}}
function calc(d){const buy=d.buyPrice>0?d.buyPrice:d.price>0?d.price:null,fb=Math.max(0,d.buyFee??1),fs=Math.max(0,d.sellFee??1);
const qty=d.shares!=null?Math.max(0,Math.floor(d.shares)):buy>0&&d.budget!=null?Math.max(0,Math.floor((d.budget-fb)/buy)):0;
const rate=Math.min(100,Math.max(0,d.taxRate??26.375))/100,allow=Math.max(0,d.allowance??0);
const invested=buy!=null?qty*buy+fb:null;
function netAt(price){if(!qty||buy==null)return null;const pre=qty*price-qty*buy-fb-fs;return pre-Math.max(0,pre-allow)*rate}
function targetForNet(wanted){if(!qty||buy==null)return null;const gross=wanted>=allow?allow+(wanted-allow)/(1-rate):wanted;return (qty*buy+fb+fs+gross)/qty}
return {buy,qty,fb,fs,rate,allow,invested,netAt,targetForNet}}
function renderCalc(){const d=get(),c=calc(d),goals=[5,10,15,18,20];if(d.customPct!=null&&!goals.includes(d.customPct))goals.push(d.customPct);goals.sort((a,b)=>a-b);
$('profitRows').innerHTML=goals.map(p=>{if(!c.buy||!c.qty)return `<tr><td>${sign(p,1)} %</td><td colspan="4">Einstieg und Budget oder Stückzahl eingeben</td></tr>`;
const target=c.buy*(1+p/100),gross=(target-c.buy)*c.qty,net=c.netAt(target);
return `<tr><td>${sign(p,1)} %</td><td>${money(target)}</td><td>${sign(target-c.buy,3)} €</td><td class="${gross<0?'bad':'good'}">${sign(gross)} €</td><td class="${net<0?'bad':'good'}">${sign(net)} €</td></tr>`}).join('');
$('tradeSummary').innerHTML=metric('Stückzahl',String(c.qty))+metric('Kaufkosten',money(c.invested))+metric('Budgetrest',d.budget!=null&&c.invested!=null?money(d.budget-c.invested):'–')+metric('Steuerannahme',fmt(c.rate*100,3)+' %');
let fixed=null,trail=null;
if(c.buy!=null){if(d.stopEuro!=null)fixed=c.buy-d.stopEuro;else if(d.stopPct!=null)fixed=c.buy*(1-d.stopPct/100);
const high=d.highest>0?d.highest:c.buy;if(d.trailEuro!=null)trail=high-d.trailEuro;else if(d.trailPct!=null)trail=high*(1-d.trailPct/100)}
const desired=d.desiredNet!=null?c.targetForNet(d.desiredNet):null;
$('stopSummary').innerHTML=metric('Fester Stopkurs',fixed==null?'–':money(fixed))+metric('Trailing-Stopkurs',trail==null?'–':money(trail))+metric('Stop für Nettogewinn',desired==null?'–':money(desired))+metric('Netto bei Trailing-Stop',trail==null?'–':money(c.netAt(trail)));const maxLoss=parse($('riskMax').value)??30;const stopRisk=c.qty&&c.buy?Math.max(0,(c.qty*c.buy+c.fb+c.fs-maxLoss)/c.qty):null;$('riskPreview').innerHTML=metric('Stückzahl',String(c.qty))+metric('Verlustlimit',money(maxLoss))+metric('Rechnerischer Stop',stopRisk==null?'–':money(stopRisk))+metric('Max. Kursrückgang',stopRisk==null?'–':sign((stopRisk/c.buy-1)*100)+' %');
}
function render(){const d=get(),e=evaluate(d),m=[];
for(const [key,label] of [['sma50','Abstand SMA 50'],['sma200','Abstand SMA 200']])if(d.price!=null&&d[key]>0){const diff=d.price-d[key];m.push(metric(label,`${sign(diff)} € · ${sign(diff/d[key]*100)} %`,diff>=0?'good':'bad'))}
m.push(metric('RSI (14)',fmt(d.rsi,1),d.rsi>=70?'warn':''));
m.push(metric('Umsatzwachstum',typeof e.sg==='number'?sign(e.sg)+' %':e.sg||'–'));
m.push(metric('Gewinnentwicklung',typeof e.pg==='number'?sign(e.pg)+' %':e.pg||'–'));
if(d.price>0&&d.target!=null)m.push(metric('Kursziel-Potenzial',sign((d.target/d.price-1)*100)+' %'));
m.push(metric('Orientierungs-Score',e.score==null?'–':e.score+'/100'));
m.push(metric('Anlagerisiko',({good:'Gering',neutral:'Mittel',bad:'Hoch'})[d.risk]||'Nicht bewertet'));
$('metrics').innerHTML=m.join('');
$('coverage').textContent=`${e.covered} Kennzahlen vorhanden · Datensicherheit: ${e.reliability}. Ranking berücksichtigt nur vorhandene Werte.`;
let note=e.reasons.join(' · ')||'Für eine technische Einschätzung Kurs, SMA 50, SMA 200 und RSI ergänzen.';
if(d.price>0&&d.sma50>0&&d.price>d.sma50&&d.rsi>=65)note+=' · Dip: Rücksetzer Richtung SMA 50 beobachten.';
if(d.price>0&&d.sma50>0&&d.price<d.sma50)note+=' · Unter SMA 50: Stabilisierung abwarten.';
if(d.price>0&&d.sma200>0&&d.price<d.sma200)note+=' · Unter SMA 200: Langfristiger Trend möglicherweise schwach.';
$('interpret').textContent=note+' Keine Kaufempfehlung.';renderCalc()}
function saveState(){try{localStorage.setItem(K,JSON.stringify(entries));localStorage.setItem(CK,JSON.stringify({bookings,actualTotal}));localStorage.setItem(TK,JSON.stringify({positions,sales,settings}));return true}catch(e){alert('Speichern fehlgeschlagen. Bitte Speicherplatz und Browser-Einstellungen prüfen.');return false}}
function load(){try{const e=JSON.parse(localStorage.getItem(K)||'[]');entries=Array.isArray(e)?e:[]}catch{entries=[]}
try{const c=JSON.parse(localStorage.getItem(CK)||'{}');bookings=Array.isArray(c.bookings)?c.bookings:[];actualTotal=typeof c.actualTotal==='number'?c.actualTotal:null}catch{bookings=[];actualTotal=null}
try{const t=JSON.parse(localStorage.getItem(TK)||'{}');positions=Array.isArray(t.positions)?t.positions:[];sales=Array.isArray(t.sales)?t.sales:[];settings={goal:658,tax:26.375,lossStart:0,startYear:2026,startMonth:10,...(t.settings||{})}}catch{positions=[];sales=[]}}
function reset(){editId=null;for(const [id] of all)$(id).value='';$('notes')&&($('notes').value='');$('riskMax').value='30';$('buyFee').value='1';$('sellFee').value='1';$('taxRate').value='26,375';$('saveBtn').textContent='In Watchlist speichern';$('saveStatus').textContent='';render()}
function tab(t){for(const id of ['analyze','watch','bought','capital','wissen'])$(id).classList.toggle('hidden',id!==t);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));if(t==='watch')renderWatch();if(t==='wissen'&&window.initWissen)window.initWissen();if(t==='capital'){renderCapital();renderTrades()}if(t==='bought')renderTrades();document.querySelectorAll('#'+t+' details').forEach(d=>d.open=false)}
function normId(x){return String(x||'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function findPosition(d){const id=normId(d.isin||d.wkn);return positions.find(p=>positionQty(p)>0.000001&&(id&&[p.isin,p.wkn].some(v=>normId(v)===id)||(!id&&p.name.trim().toLowerCase()===String(d.name||'').trim().toLowerCase())))||null}
function riskFor(d){const c=calc(d),limit=Math.max(0,d.riskMax??30);if(!c.qty||!c.buy)return null;const stop=Math.max(0,(c.qty*c.buy+c.fb+c.fs-limit)/c.qty);return {qty:c.qty,stop,fall:(c.buy-stop)/c.buy*100,limit}}
function renderWatch(){$('count').textContent=entries.length;
const sorted=entries.map(x=>({...x,e:evaluate(x.data),p:findPosition(x.data)})).sort((a,b)=>(b.e.score??-1)-(a.e.score??-1));
const groups=[['Kaufkandidaten',sorted.filter(x=>!x.p)],['Bereits gekauft · verknüpft',sorted.filter(x=>x.p)]];
$('watchItems').innerHTML=groups.map(([title,arr],i)=>`<details class="fold" ${i===0?'open':''}><summary>${esc(title)} <span class="muted">(${arr.length})</span></summary><div class="fold-body">${arr.length?arr.map(x=>{const d=x.data,c=calc(d),r=riskFor(d);return `<details class="fold"><summary>${esc(d.name||'Ohne Namen')} · Score ${x.e.score??'–'}/100 ${x.p?'· Im Depot':''}</summary><div class="fold-body"><div class="muted">Kurs ${d.price==null?'–':money(d.price)} · SMA50 ${d.sma50==null?'–':money(d.sma50)} · SMA200 ${d.sma200==null?'–':money(d.sma200)}</div><div class="mini">${c.buy&&c.qty?'Einstieg '+money(c.buy)+' · '+c.qty+' Stück · '+[5,10,15,18,20].map(v=>'+'+v+'%: '+money(c.buy*(1+v/100))).join(' · '):'Einstieg und Budget in der Analyse ergänzen'}</div><div class="mini">${r?'Worst Case '+money(r.limit)+': Stop '+money(r.stop)+' ('+sign(-r.fall)+' %) · Gebühren berücksichtigt':'Worst Case: Budget und Einstieg fehlen'}</div><div class="buttons"><button data-buy="${esc(x.id)}">${x.p?'Nachkaufen':'Kaufen'}</button><button data-edit="${esc(x.id)}">Bearbeiten</button><button class="danger" data-delete="${esc(x.id)}">Löschen</button></div></div></details>`}).join(''):'<p class="hint">Keine Einträge.</p>'}</div></details>`).join('')}
function totals(){let deposits=0,withdrawals=0,profits=0,interest=0;for(const b of bookings){const v=b.amount;switch(b.type){case'deposit':deposits+=v;break;case'withdrawal':withdrawals+=v;break;case'profit':profits+=v;break;case'interest':interest+=v;break}}
profits+=sales.reduce((s,x)=>s+x.net,0);return {deposits,withdrawals,profits,interest,total:deposits-withdrawals+profits+interest}}
// Kapitalfluss aus echten Buchungen und Trades. Käufe sind Vermögensumschichtung, kein Verlust.
function portfolioLedger(){
const t=totals();let purchases=0,openCost=0,saleCash=0,knownMarket=0,priced=0,unpriced=[];
for(const p of positions){for(const l of p.lots||[]){purchases+=(Number(l.qty)||0)*(Number(l.price)||0)+(Number(l.fee)||0);openCost+=(Number(l.remaining)||0)*((Number(l.price)||0)+(Number(l.fee)||0)/Math.max(1,Number(l.qty)||1))}
const q=positionQty(p);if(q<=0)continue;const e=entries.find(x=>normId(x.data.isin)&&normId(x.data.isin)===normId(p.isin)||normId(x.data.wkn)&&normId(x.data.wkn)===normId(p.wkn)||String(x.data.name||'').trim().toLocaleLowerCase('de')===String(p.name||'').trim().toLocaleLowerCase('de'));
const price=e?Number(e.data.price):NaN;if(Number.isFinite(price)&&price>0){knownMarket+=q*price;priced++}else unpriced.push(p.name)}
for(const x of sales)saleCash+=(Number(x.qty)||0)*(Number(x.price)||0)-(Number(x.fee)||0)-(Number(x.tax)||0);
// Manuelle Gewinnbuchungen sind keine verifizierten Verkaufserlöse. Sie zählen für die Challenge,
// nicht automatisch als Cash: Sonst würden historische Verkäufe doppelt verbucht.
const cash=t.deposits-t.withdrawals+t.interest-purchases+saleCash;
const realized=sales.reduce((n,x)=>n+(Number(x.net)||0),0);
const cashAdjusted=t.deposits-t.withdrawals+t.interest+bookings.filter(x=>x.type==='profit').reduce((n,x)=>n+x.amount,0)-purchases+saleCash;
return {t,purchases,openCost,saleCash,cash,cashAdjusted,realized,knownMarket,priced,unpriced,manualCount:bookings.filter(x=>x.type==='profit').length};}
function dashboardChart(){const d=portfolioLedger(), el=$('depotDashboard');if(!el)return;
const months={};for(const s of sales){const k=String(s.date||'').slice(0,7);months[k]=(months[k]||0)+(Number(s.net)||0)}for(const b of bookings)if(b.type==='profit'){const k=String(b.date||'').slice(0,7);months[k]=(months[k]||0)+b.amount}
const sorted=Object.entries(months).sort((a,b)=>a[0].localeCompare(b[0])).slice(-12),max=Math.max(1,...sorted.map(x=>Math.abs(x[1])));
const monthly=sorted.map(([m,v])=>`<div class="dash-month" title="${esc(m)}: ${sign(v)} €"><div class="dash-month-bar" style="height:${Math.max(3,Math.round(Math.abs(v)/max*105))}px;background:${v>=0?'#16896f':'#c45454'}"></div><div class="dash-month-label">${esc(m.slice(5))}/${esc(m.slice(2,4))}</div></div>`).join('');
const chartItems=positions.map(p=>({name:p.name,cost:(p.lots||[]).reduce((n,l)=>n+(Number(l.remaining)||0)*((Number(l.price)||0)+(Number(l.fee)||0)/Math.max(1,Number(l.qty)||1)),0)})).filter(x=>x.cost>0).sort((a,b)=>b.cost-a.cost);const colors=['#356bc1','#16896f','#9969bf','#d3a044','#d57d68','#6b91a7'];const total=chartItems.reduce((n,x)=>n+x.cost,0);let acc=0;const slices=chartItems.map((x,i)=>{const st=acc;acc+=x.cost/total*100;return `${colors[i%colors.length]} ${st}% ${acc}%`}).join(',');const legend=chartItems.slice(0,10).map((x,i)=>`<span><i class="dash-dot" style="background:${colors[i%colors.length]}"></i>${esc(x.name)} ${fmt(x.cost/total*100,1)} %</span>`).join('');
const year=new Date().getFullYear(),goal=yearGoal(year),yearProfit=sales.filter(x=>String(x.date).startsWith(String(year))).reduce((n,x)=>n+(Number(x.net)||0),0)+bookings.filter(x=>x.type==='profit'&&String(x.date).startsWith(String(year))).reduce((n,x)=>n+x.amount,0);const pct=goal>0?Math.max(0,Math.min(100,yearProfit/goal*100)):0;
const coverage=d.unpriced.length?`Für ${d.unpriced.length} offene Position(en) fehlt ein zugeordneter aktueller Kurs (${esc(d.unpriced.join(', '))}). Marktwert und Gesamtvermögen deshalb nicht vollständig berechenbar.`:'Kurse stammen aus deiner manuell gepflegten Watchlist und können veraltet sein.';
const manual=d.manualCount?`Achtung: ${d.manualCount} manuelle Gewinn-/Verlustbuchung(en) sind für die Jahres-Challenge enthalten, aber nicht automatisch als Cash gebucht. Prüfe, ob diese bereits in den erfassten Verkäufen stecken. Ohne vollständige frühere Transaktionen kann der Cashbestand abweichen.`:'';
const cashValid=d.cash>=-0.005;
const cashNote=cashValid?'':'Rechnerisches Cash ist negativ: möglicherweise fehlen ältere Einzahlungen, Verkäufe oder es gibt Doppelbuchungen.';
el.innerHTML=`<div class="dash-grid"><div class="dash-panel"><h4>💶 Cash & Einlagen</h4><div class="metrics">${metric('Einzahlungen',money(d.t.deposits))}${metric('Auszahlungen',money(d.t.withdrawals))}${metric('Freies Cash (rechnerisch)',money(d.cash),d.cash<0?'bad':'good')}${metric('Aktienkäufe gesamt',money(d.purchases))}${metric('Offener Einstandswert',money(d.openCost))}${metric('Netto-Verkaufserlöse',money(d.saleCash))}</div><div class="dash-summary">Cash = Einzahlungen − Auszahlungen + Zinsen − alle Käufe + Netto-Verkaufserlöse.</div></div><div class="dash-panel"><h4>📈 Depot & Gewinnschwelle</h4><div class="metrics">${metric('Aktienwert (bekannte Kurse)',d.unpriced.length?'Teilwert '+money(d.knownMarket):money(d.knownMarket))}${metric('Gesamtvermögen',d.unpriced.length?'Nicht vollständig':money(d.cash+d.knownMarket))}${metric('Gesamtergebnis',d.unpriced.length?'Nicht vollständig':sign(d.cash+d.knownMarket-(d.t.deposits-d.t.withdrawals))+' €')}${metric('Gewinnschwelle Depot',money(d.t.deposits-d.t.withdrawals-d.cash))}</div><div class="dash-summary">Gewinnschwelle = Nettoeinzahlungen − freies Cash. Marktwert berücksichtigt nur manuell hinterlegte Kurse.</div></div><div class="dash-panel"><h4>🥧 Aktienverteilung nach Einstand</h4>${total>0?`<div style="width:142px;height:142px;border-radius:50%;margin:8px auto;background:conic-gradient(${slices})"></div><div class="dash-legend">${legend}</div>`:'<p class="hint">Noch keine offenen Aktienpositionen.</p>'}</div><div class="dash-panel"><h4>📊 Realisierte Monatsgewinne / -verluste</h4>${sorted.length?`<div class="dash-chart">${monthly}</div>`:'<p class="hint">Noch keine abgeschlossenen Ergebnisse.</p>'}<div class="dash-summary">Netto nach erfassten Gebühren und Steuern; manuelle Ergebnisbuchungen mitgerechnet.</div></div><div class="dash-panel"><h4>🎯 Jahresziel ${year}</h4><strong>${sign(yearProfit)} € / ${money(goal)}</strong><div class="dash-bar" style="margin-top:12px"><span style="width:${pct}%;background:#16896f"></span></div><div class="dash-summary">${fmt(pct,1)} % erreicht · Noch benötigt: ${money(Math.max(0,goal-yearProfit))}. Realisierte Verluste erhöhen den verbleibenden Zielbetrag, nicht das ursprüngliche Ziel.</div></div></div><div class="dash-warning">${coverage} ${manual} ${cashNote}</div>`;
}
function renderCapital(){const t=totals();$('capitalMetrics').innerHTML=metric('Einzahlungen',money(t.deposits))+metric('Auszahlungen',money(t.withdrawals))+metric('Gewinne / Verluste netto',sign(t.profits)+' €',t.profits<0?'bad':'good')+metric('Zinsen netto',sign(t.interest)+' €',t.interest<0?'bad':'good')+metric('Kapital inkl. realisierter Ergebnisse',money(t.total))+metric('Ergebnis netto',sign(t.profits+t.interest)+' €',t.profits+t.interest<0?'bad':'good')+metric('Einfache Rendite',t.deposits-t.withdrawals>0?sign((t.profits+t.interest)/(t.deposits-t.withdrawals)*100)+' %':'–');
dashboardChart();$('capitalExplain').textContent='Gesamtkapital = Einzahlungen − Auszahlungen + realisierte Nettoergebnisse + Nettozinsen. Keine zeitgewichtete Rendite. Bei Gewinn-/Verlustbuchungen nur den Gewinnanteil erfassen, nicht den gesamten Verkaufserlös.';
$('actualTotal').value=actualTotal??'';
$('actualMetrics').innerHTML=metric('Aktueller Gesamtwert',actualTotal==null?'–':money(actualTotal))+metric('Differenz zum rechnerischen Kapital',actualTotal==null?'–':sign(actualTotal-t.total)+' €',actualTotal!=null&&actualTotal-t.total<0?'bad':'good');
const names={deposit:'Einzahlung',withdrawal:'Auszahlung',profit:'Gewinn / Verlust netto',interest:'Zinsen netto'};
$('bookings').innerHTML=bookings.length?[...bookings].sort((a,b)=>b.date.localeCompare(a.date)).map(b=>`<div class="item"><div><strong>${esc(b.date)} · ${esc(names[b.type])}</strong><div class="${b.amount<0?'bad':'good'}">${sign(b.amount)} €</div><div class="muted">${esc(b.note||'')}</div></div><div class="buttons"><button data-book-edit="${esc(b.id)}">Bearbeiten</button><button class="danger" data-book-del="${esc(b.id)}">Löschen</button></div></div>`).join(''):'<p class="muted">Noch keine Buchungen.</p>';foldBookings()}

function foldBookings(){const root=$('bookings');const rows=[...bookings].sort((a,b)=>b.date.localeCompare(a.date));const types={deposit:'Einzahlung',withdrawal:'Auszahlung',profit:'Gewinn/Verlust',interest:'Zinsen'};const years=[...new Set(rows.map(b=>b.date.slice(0,4)))];root.innerHTML=years.map((year,yi)=>{const months=[...new Set(rows.filter(b=>b.date.startsWith(year)).map(b=>b.date.slice(0,7)))];return `<details class="fold" ${yi===0?'open':''}><summary>${year} · ${rows.filter(b=>b.date.startsWith(year)).length} Buchungen</summary><div class="fold-body">${months.map((month,mi)=>{const list=rows.filter(b=>b.date.startsWith(month));const deposits=list.filter(b=>b.type==='deposit').reduce((n,b)=>n+b.amount,0);const gains=list.filter(b=>b.type==='profit').reduce((n,b)=>n+b.amount,0);return `<details class="fold" ${yi===0&&mi===0?'open':''}><summary>${month} · ${list.length} Buchungen <span class="muted">Einzahlungen ${money(deposits)} · Gewinne ${sign(gains)} €</span></summary><div class="fold-body">${list.map(b=>`<div class="item"><div><strong>${esc(b.date)} · ${types[b.type]}</strong><div class="${b.amount<0?'bad':'good'}">${sign(b.amount)} €</div><div class="muted">${esc(b.note||'')}</div></div><div class="buttons"><button data-book-edit="${esc(b.id)}">Bearbeiten</button><button class="danger" data-book-del="${esc(b.id)}">Löschen</button></div></div>`).join('')}</div></details>`}).join('')}</div></details>`}).join('')||'<p class="hint">Noch keine Buchungen.</p>'}
function bookReset(){bookEdit=null;$('bookingType').value='deposit';$('bookingAmount').value='';$('bookingDate').value=new Date().toLocaleDateString('en-CA');$('bookingNote').value='';$('bookingSave').textContent='Buchung speichern'}
function exportAll(){const data={format:'aktien-cockpit',version:'4.8',exportedAt:new Date().toISOString(),entries,capital:{bookings,actualTotal},trading:{positions,sales,settings}};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='aktien_cockpit_4_8_backup.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function validEntries(a){return Array.isArray(a)&&a.length<=10000&&a.every(x=>x&&typeof x.id==='string'&&x.id.length<200&&x.data&&typeof x.data==='object'&&!Array.isArray(x.data))}
function validCapital(c){return c&&Array.isArray(c.bookings)&&c.bookings.length<=50000&&c.bookings.every(b=>b&&typeof b.id==='string'&&['deposit','withdrawal','profit','interest'].includes(b.type)&&typeof b.amount==='number'&&Number.isFinite(b.amount)&&typeof b.date==='string')&&(c.actualTotal==null||typeof c.actualTotal==='number'&&Number.isFinite(c.actualTotal))}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const el=$(b.dataset.toggle);el.classList.toggle('hidden');b.textContent=el.classList.contains('hidden')?'Öffnen ▾':'Schließen ▴'});
document.addEventListener('click',e=>{const b=e.target.closest('[data-minus-for]');if(!b)return;const input=$(b.dataset.minusFor);if(!input)return;const value=input.value.trim();input.value=value.startsWith('-')?value.slice(1):'-'+value;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-tip]');if(b){$('helpTitle').textContent=b.dataset.title;$('helpText').textContent=b.dataset.tip;$('help').showModal()}});
$('analyze').addEventListener('input',render);$('analyze').addEventListener('change',render);$('riskMax').addEventListener('input',render);
$('newBtn').onclick=()=>{reset();tab('analyze');scrollTo(0,0)};
$('clearBtn').onclick=reset;
$('saveBtn').onclick=()=>{const d=get();if(!d.name){alert('Bitte Aktiennamen eingeben.');return}const updated=new Date().toLocaleString('de-DE');
if(editId){const e=entries.find(x=>x.id===editId);if(e){e.data=d;e.updated=updated}}else{const duplicate=entries.find(x=>(d.isin&&normId(x.data.isin)===normId(d.isin))||(d.wkn&&normId(x.data.wkn)===normId(d.wkn)));if(duplicate){alert('Diese ISIN/WKN ist bereits in der Watchlist. Bitte den vorhandenen Eintrag bearbeiten.');return}editId=crypto.randomUUID();entries.push({id:editId,data:d,updated})}
if(saveState()){$('saveBtn').textContent='Änderungen speichern';$('saveStatus').textContent='✓ Lokal gespeichert';renderWatch()}};
$('watchItems').onclick=e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]'),buy=e.target.closest('[data-buy]');
if(buy){const x=entries.find(x=>x.id===buy.dataset.buy);if(x){const p=findPosition(x.data);openBuy(p?p.name:x.data.name,p?.id||null);$('tPrice').value=x.data.buyPrice||x.data.price||'';tab('bought')}}
if(edit){const x=entries.find(x=>x.id===edit.dataset.edit);if(!x)return;editId=x.id;set(x.data);$('saveBtn').textContent='Änderungen speichern';tab('analyze');scrollTo(0,0)}
if(del){const x=entries.find(x=>x.id===del.dataset.delete);if(x&&confirm('Aktie wirklich löschen?')){entries=entries.filter(y=>y.id!==x.id);if(editId===x.id)reset();saveState();renderWatch()}}};
$('exportBtn').onclick=exportAll;$('capitalExport').onclick=exportAll;
$('importFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Datei zu groß');const data=JSON.parse(await file.text());
if(!validEntries(data.entries))throw Error('Ungültige Watchlist');if(data.capital&&!validCapital(data.capital))throw Error('Ungültige Kapitalbuchungen');
if(!confirm('Import ersetzt die vorhandene Watchlist'+(data.capital?' und Kapitalbuchungen':'')+'. Vorher Backup exportieren! Fortfahren?'))return;
const oldEntries=entries,oldBookings=bookings,oldActual=actualTotal,oldPositions=positions,oldSales=sales,oldSettings=settings;
entries=data.entries;if(data.capital){bookings=data.capital.bookings;actualTotal=data.capital.actualTotal??null}
if(data.trading){if(!Array.isArray(data.trading.positions)||!Array.isArray(data.trading.sales))throw Error('Ungültige Trades');positions=data.trading.positions;sales=data.trading.sales;settings={goal:658,tax:26.375,lossStart:0,startYear:2026,startMonth:10,...data.trading.settings}}
if(!saveState()){entries=oldEntries;bookings=oldBookings;actualTotal=oldActual;positions=oldPositions;sales=oldSales;settings=oldSettings;throw Error('Lokales Speichern fehlgeschlagen')}
renderWatch();renderCapital();renderTrades();alert('Import erfolgreich. '+entries.length+' Aktien geladen.')}catch(err){alert('Import fehlgeschlagen: '+err.message)}finally{e.target.value=''}};
$('bookingSave').onclick=()=>{const amount=parse($('bookingAmount').value),date=$('bookingDate').value,type=$('bookingType').value;
if(amount==null||!date){alert('Bitte gültigen Betrag und Datum eingeben.');return}
const b={id:bookEdit||crypto.randomUUID(),date,type,amount,note:$('bookingNote').value.trim()};
if(bookEdit){const i=bookings.findIndex(x=>x.id===bookEdit);if(i>=0)bookings[i]=b;else bookings.push(b)}else bookings.push(b);
if(saveState()){bookReset();renderCapital();renderTrades()}};
$('bookingReset').onclick=bookReset;
$('bookings').onclick=e=>{const ed=e.target.closest('[data-book-edit]'),del=e.target.closest('[data-book-del]');
if(ed){const b=bookings.find(x=>x.id===ed.dataset.bookEdit);if(!b)return;bookEdit=b.id;$('bookingType').value=b.type;$('bookingAmount').value=String(b.amount).replace('.',',');$('bookingDate').value=b.date;$('bookingNote').value=b.note||'';$('bookingSave').textContent='Änderungen speichern';$('bookingAmount').focus()}
if(del){const b=bookings.find(x=>x.id===del.dataset.bookDel);if(b&&confirm('Buchung wirklich löschen?')){bookings=bookings.filter(x=>x.id!==b.id);saveState();renderCapital();renderTrades()}}};
$('actualSave').onclick=()=>{const v=parse($('actualTotal').value);if($('actualTotal').value.trim()&&v==null){alert('Ungültiger Kontowert');return}actualTotal=v;if(saveState())renderCapital()};

function val(id){return parse($(id).value)}
function day(){return new Date().toLocaleDateString('en-CA')}
function openBuy(name='',id=null){tradePosition=id;$('sellEditor').classList.add('hidden');$('tradeEditor').classList.remove('hidden');$('tradeTitle').textContent=id?'Nachkauf erfassen':'Kauf erfassen';$('tName').value=name;$('tName').readOnly=!!id;$('tDate').value=day();$('tQty').value='';$('tPrice').value='';$('tFee').value='1';$('tradeEditor').scrollIntoView({block:'nearest'})}
function closeEditors(){$('tradeEditor').classList.add('hidden');$('sellEditor').classList.add('hidden')}
function openSell(id){sellPosition=id;const p=positions.find(x=>x.id===id);if(!p)return;$('tradeEditor').classList.add('hidden');$('sellEditor').classList.remove('hidden');$('sellTitle').textContent=p.name+' verkaufen';$('sDate').value=day();$('sQty').value=String(p.lots.reduce((s,l)=>s+l.remaining,0));$('sPrice').value='';$('sFee').value='1';$('sTaxMode').value='actual';$('sTaxActual').value='';previewSale();$('sellEditor').scrollIntoView({block:'nearest'})}
function positionQty(p){return p.lots.reduce((s,l)=>s+l.remaining,0)}
function fifo(p,qty){let remaining=qty,cost=0,allocation=[];for(const l of p.lots){const q=Math.min(remaining,l.remaining);if(q>0){const perFee=l.fee/l.qty;cost+=q*(l.price+perFee);allocation.push({lotId:l.id,qty:q,date:l.date});remaining-=q}if(remaining<=0.000001)break}return remaining>0.000001?null:{cost,allocation}}
function saleCalc(){const p=positions.find(x=>x.id===sellPosition),q=val('sQty'),price=val('sPrice'),fee=val('sFee')??0;if(!p||q==null||q<=0||q>positionQty(p)+1e-7||price==null||price<0||fee<0)return null;const f=fifo(p,q);if(!f)return null;const gross=q*price-f.cost-fee;const priorLoss=Math.max(0,settings.lossStart+sales.reduce((s,x)=>s+(x.gross<0?-x.gross:0)-(x.lossUsed||0),0));const lossUsed=Math.min(Math.max(0,gross),priorLoss);const estimate=Math.max(0,gross-lossUsed)*settings.tax/100;const actual=val('sTaxActual');const tax=$('sTaxMode').value==='actual'?actual:estimate;if(tax==null||tax<0)return {gross,estimate,lossUsed,invalidTax:true};return {gross,estimate,lossUsed,tax,net:gross-tax,allocation:f.allocation,cost:f.cost,q,price,fee,p}}
function previewSale(){const c=saleCalc();$('actualTaxField').classList.toggle('hidden',$('sTaxMode').value!=='actual');$('sellPreview').textContent=!c?'Bitte Stückzahl und Verkaufskurs eingeben.':c.invalidTax?`Vor Steuer: ${money(c.gross)} · Steuer-Schätzung: ${money(c.estimate)}. Bitte tatsächlichen Steuerabzug eintragen (auch 0 €).`:`Gewinn vor Steuern: ${money(c.gross)} · Steuer: ${money(c.tax)} · Netto: ${money(c.net)} · verrechneter Verlust (Schätzung): ${money(c.lossUsed)}`}
function yearGoal(y){const manual=settings.yearGoals?.[y];if(manual!=null&&Number.isFinite(Number(manual)))return Number(manual);return y===(settings.startYear??2026)?settings.goal*(13-(settings.startMonth??10))/12:settings.goal}
$('yearGoals').onclick=e=>{const b=e.target.closest('[data-year-save]');if(!b)return;const year=Number(b.dataset.yearSave),v=parse(document.querySelector(`[data-year-goal="${year}"]`).value);if(v==null||v<0){alert('Bitte gültiges Jahresziel eingeben.');return}settings.yearGoals={...(settings.yearGoals||{}),[year]:v};saveState();renderTrades()};
// Auswertung abgeschlossener Verkäufe; Buchungen ohne Aktienbezug werden separat gezeigt.
function saleEfficiency(s){
 const cost=Number(s.cost)||0, net=Number(s.net)||0, alloc=Array.isArray(s.allocation)?s.allocation:[];
 const days=alloc.length?alloc.reduce((sum,a)=>sum+(Number(a.qty)||0)*Math.max(0,Math.round((Date.parse(s.date)-Date.parse(a.date))/86400000)),0)/Math.max(0.000001,alloc.reduce((sum,a)=>sum+(Number(a.qty)||0),0)):(Number(s.durationMin)||0)+(Number(s.durationMax)||0)>0?((Number(s.durationMin)||0)+(Number(s.durationMax)||0))/2:null;
 const pct=cost>0?net/cost*100:null;
 // Tage 0: keine sinnvolle 30-Tage-Hochrechnung; Werte bleiben sichtbar als „–“.
 return {cost,net,days,pct,per30:days>0&&pct!=null?pct*30/days:null,eur30:days>0?net*30/days:null};
}
function effNum(v,d=1){return v==null||!Number.isFinite(v)?'–':fmt(v,d)}
function effCard(s){const x=saleEfficiency(s);return `<details class="fold"><summary>📊 Effizienz · ${x.pct==null?'–':sign(x.pct)+' %'} netto · ${x.days==null?'–':effNum(x.days)+' Tage'}</summary><div class="fold-body"><div class="metrics">${metric('Nettogewinn',sign(x.net)+' €',x.net<0?'bad':'good')}${metric('Nettorendite',x.pct==null?'–':sign(x.pct)+' %')}${metric('Ø Haltedauer',x.days==null?'–':effNum(x.days)+' Tage')}${metric('Rendite / 30 Tage',x.per30==null?'–':sign(x.per30)+' %')}${metric('Gewinn / 30 Tage',x.eur30==null?'–':sign(x.eur30)+' €')}${metric('Kaufkosten inkl. Gebühren',money(x.cost))}</div><p class="hint">30-Tage-Werte sind nur lineare Vergleichsgrößen, keine erzielbare Folgerendite. Haltedauer bei Teilverkäufen nach Stückzahl der FIFO-Kauftranchen gewichtet.</p></div></details>`}
function effSummary(items){const xs=items.map(saleEfficiency),n=xs.length,net=xs.reduce((a,x)=>a+x.net,0),cost=xs.reduce((a,x)=>a+x.cost,0),valid=xs.filter(x=>x.days!=null),avgDays=valid.length?valid.reduce((a,x)=>a+x.days,0)/valid.length:null,valid30=xs.filter(x=>x.per30!=null),avg30=valid30.length?valid30.reduce((a,x)=>a+x.per30,0)/valid30.length:null,avgEuro30=valid30.length?valid30.reduce((a,x)=>a+x.eur30,0)/valid30.length:null,wins=xs.filter(x=>x.net>0).length,losses=xs.filter(x=>x.net<0).length;return {n,net,cost,pct:cost>0?net/cost*100:null,avgDays,avg30,avgEuro30,wins,losses,winRate:n?wins/n*100:null}}
function effMetrics(items){const x=effSummary(items);return `<div class="metrics">${metric('Nettogewinn Trades',sign(x.net)+' €',x.net<0?'bad':'good')}${metric('Nettorendite auf Verkäufe',x.pct==null?'–':sign(x.pct)+' %')}${metric('Ø Haltedauer',effNum(x.avgDays)+' Tage')}${metric('Ø Rendite / 30 Tage',x.avg30==null?'–':sign(x.avg30)+' %')}${metric('Ø Gewinn / 30 Tage',x.avgEuro30==null?'–':sign(x.avgEuro30)+' €')}${metric('Trefferquote',x.winRate==null?'–':effNum(x.winRate)+' %')}${metric('Verkäufe',String(x.n))}${metric('Gewinn / Verlust',x.wins+' / '+x.losses)}</div>`}
function effGroups(items){const bands=[['Kurz · 0–14 Tage',x=>x.days!=null&&x.days<=14],['Mittel · 15–60 Tage',x=>x.days>14&&x.days<=60],['Lang · über 60 Tage',x=>x.days>60]];return bands.map(([label,fn])=>{const subset=items.filter(s=>fn(saleEfficiency(s)));return `<details class="fold"><summary>${label} · ${subset.length} Verkäufe</summary><div class="fold-body">${effMetrics(subset)}</div></details>`}).join('')}
function renderEfficiency(){const keys=[...new Set(sales.map(s=>s.date.slice(0,4)))].sort().reverse();$('efficiencyStats').innerHTML='<p class="hint">Nettorendite = Summe realisierter Nettoergebnisse ÷ Summe der zugehörigen Kaufkosten. Das ist eine Rendite auf verkaufte Positionen, keine Depot- oder Jahreskapitalrendite. Ein Teilverkauf zählt als ein Verkauf; Trefferquote entsprechend je Verkauf. Manuelle Gewinnbuchungen sind hier nicht enthalten, bleiben aber in der ETF-Challenge.</p>'+keys.map((y,yi)=>{const yearItems=sales.filter(s=>s.date.startsWith(y)),months=[...new Set(yearItems.map(s=>s.date.slice(0,7)))].sort().reverse();return `<details class="fold" ${yi===0?'open':''}><summary>📅 ${y} · ${yearItems.length} Verkäufe · ${sign(effSummary(yearItems).net)} € netto</summary><div class="fold-body">${effMetrics(yearItems)}<h4>Haltedauer-Vergleich</h4>${effGroups(yearItems)}<h4>Monate</h4>${months.map((m,mi)=>{const monthItems=yearItems.filter(s=>s.date.startsWith(m));return `<details class="fold" ${yi===0&&mi===0?'open':''}><summary>${m} · ${monthItems.length} Verkäufe · ${sign(effSummary(monthItems).net)} € netto</summary><div class="fold-body">${effMetrics(monthItems)}${effGroups(monthItems)}</div></details>`}).join('')}</div></details>`}).join('')||'<p class="hint">Noch keine Verkäufe für die Effizienzanalyse.</p>'}
function simulatorHtml(p,qty,invest,avg){return `<details class="fold"><summary>🧮 Nachkauf-Simulator · Durchschnittskurs berechnen</summary><div class="fold-body simulator" data-sim="${esc(p.id)}"><p class="hint">Nur eine Vorschau. Es wird kein Kauf gebucht. Der aktuelle Durchschnitt enthält anteilige Kaufgebühren.</p><div class="grid"><label class="field">Möglicher Kaufkurs (€)<input class="small-input" data-sim-input="price" inputmode="decimal" placeholder="z. B. 136"></label><label class="field">Neue Stückzahl<input class="small-input" data-sim-input="qty" inputmode="decimal" placeholder="z. B. 2"></label><label class="field">Kaufgebühr (€)<input class="small-input" data-sim-input="fee" inputmode="decimal" value="1"></label></div><div class="sim-output" data-sim-forward>Preis und Stückzahl eingeben.</div><h4>Umgekehrt: Wunsch-Durchschnittskurs</h4><div class="grid"><label class="field">Mein Ziel-Durchschnitt (€)<input class="small-input" data-sim-input="target" inputmode="decimal" placeholder="z. B. 160"></label></div><div class="sim-output" data-sim-inverse>Wunsch-Durchschnitt und Kaufkurs eingeben.</div><p class="hint">Ein niedrigerer Einstand reduziert nicht den bestehenden Kursverlust. Nur ganze Aktien im Rückwärtsrechner; Kurs- und Gebührenannahmen sind hypothetisch.</p></div></details>`}
function updateSimulator(box){const p=positions.find(x=>x.id===box.dataset.sim);if(!p)return;const q=positionQty(p),cost=p.lots.reduce((n,l)=>n+l.remaining*(l.price+l.fee/l.qty),0),avg=cost/q;const get=k=>parse(box.querySelector(`[data-sim-input="${k}"]`).value),price=get('price'),qty=get('qty'),fee=get('fee'),target=get('target'),f=box.querySelector('[data-sim-forward]'),r=box.querySelector('[data-sim-inverse]');if(price!=null&&price>=0&&qty!=null&&qty>0&&fee!=null&&fee>=0){const ncost=cost+qty*price+fee,nq=q+qty;f.innerHTML=`Neuer Durchschnitt: <strong>${money(ncost/nq)}</strong> · ${fmt(nq,2)} Stück gesamt · Kapital ${money(ncost)} · Zusätzlicher Einsatz ${money(qty*price+fee)} · Veränderung ${money(ncost/nq-avg)} je Aktie`;}else f.textContent='Bitte gültigen Kaufkurs, Stückzahl und Gebühr eingeben.';if(price==null||price<0||target==null||target<=0||fee==null||fee<0){r.textContent='Kaufkurs, Gebühr und Wunsch-Durchschnitt eingeben.';return}if(target<=price){r.textContent='Nicht erreichbar: Der gewünschte Durchschnitt muss über dem Nachkaufkurs liegen (bei bestehendem höheren Durchschnitt).';return}if(target>=avg){r.textContent='Dein bisheriger Durchschnitt liegt bereits bei '+money(avg)+' oder darunter. Kein Nachkauf erforderlich.';return}const required=(cost+fee-target*q)/(target-price);const count=Math.max(1,Math.ceil(required-1e-10));const newavg=(cost+count*price+fee)/(q+count);r.innerHTML=`Mindestens <strong>${count} ganze Aktien</strong> zu ${money(price)} kaufen · Einsatz <strong>${money(count*price+fee)}</strong> inklusive Gebühr · neuer Durchschnitt <strong>${money(newavg)}</strong> · ${fmt(q+count,2)} Aktien gesamt.`;}
function renderTrades(){const total=totals(),year=new Date().getFullYear(),yearSales=sales.filter(s=>s.date.startsWith(String(year))),yearManual=bookings.filter(b=>b.type==='profit'&&b.date.startsWith(String(year))),yearProfit=yearSales.reduce((s,x)=>s+x.net,0)+yearManual.reduce((s,x)=>s+x.amount,0),goal=yearGoal(year),remain=goal-yearProfit;
$('positions').innerHTML=positions.filter(p=>positionQty(p)>0.000001).map(p=>{const qty=positionQty(p),invest=p.lots.reduce((s,l)=>s+l.remaining*(l.price+l.fee/l.qty),0),avg=invest/qty;return `<details class="fold"><summary>${esc(p.name)} · ${fmt(qty,qty%1?3:0)} Stück · Ø ${money(avg)} · Einsatz ${money(invest)}</summary><div class="fold-body"><div class="mini">${p.lots.filter(l=>l.remaining>0).map(l=>`${esc(l.date)}: ${fmt(l.remaining,2)} × ${money(l.price)}`).join(' · ')}</div><details class="fold"><summary>📊 Haltedauer & bisherige Verkäufe</summary><div class="fold-body"><p class="mini">Ø bisherige Haltedauer offener Stücke: ${effNum(p.lots.filter(l=>l.remaining>0).reduce((n,l)=>n+l.remaining*Math.max(0,Math.round((Date.parse(day())-Date.parse(l.date))/86400000)),0)/qty)} Tage · Noch nicht realisierte Renditen werden ohne aktuellen Depotkurs nicht geschätzt.</p>${sales.some(s=>s.positionId===p.id)?effMetrics(sales.filter(s=>s.positionId===p.id)):'<p class="hint">Noch keine realisierten Verkäufe dieser Aktie.</p>'}</div></details><div class="position-tools"><strong>Stop- und Gewinnplanung</strong><div class="grid"><label class="field">Stop-Abstand (%)<input class="small-input" data-plan="stop" data-pid="${esc(p.id)}" value="${esc(p.plan?.stop??'')}" inputmode="decimal"></label><label class="field">Trailing-Abstand (%)<input class="small-input" data-plan="trail" data-pid="${esc(p.id)}" value="${esc(p.plan?.trail??'')}" inputmode="decimal"></label><label class="field">Höchstkurs (€)<input class="small-input" data-plan="high" data-pid="${esc(p.id)}" value="${esc(p.plan?.high??'')}" inputmode="decimal"></label><label class="field">Nettogewinnziel (€)<input class="small-input" data-plan="target" data-pid="${esc(p.id)}" value="${esc(p.plan?.target??50)}" inputmode="decimal"></label></div><div class="mini" data-plan-result="${esc(p.id)}"></div><button data-save-plan="${esc(p.id)}">Strategie speichern / berechnen</button></div>${simulatorHtml(p,qty,invest,avg)}<div class="buttons"><button data-add-lot="${esc(p.id)}">＋ Nachkauf</button><button data-sell-position="${esc(p.id)}">Verkaufen</button></div></div></details>`}).join('')||'<p class="hint">Noch keine offenen Positionen.</p>';

const sortedSales=[...sales].sort((a,b)=>b.date.localeCompare(a.date));const saleYears=[...new Set(sortedSales.map(x=>x.date.slice(0,4)))];$('sales').innerHTML=saleYears.map((y,yi)=>`<details class="fold" ${yi===0?'open':''}><summary>${y} · ${sign(sortedSales.filter(s=>s.date.startsWith(y)).reduce((n,s)=>n+s.net,0))} € netto</summary><div class="fold-body">${[...new Set(sortedSales.filter(s=>s.date.startsWith(y)).map(s=>s.date.slice(0,7)))].map((m,mi)=>`<details class="fold" ${yi===0&&mi===0?'open':''}><summary>${m} · ${sign(sortedSales.filter(s=>s.date.startsWith(m)).reduce((n,s)=>n+s.net,0))} €</summary><div class="fold-body">${sortedSales.filter(s=>s.date.startsWith(m)).map(s=>`<div class="item"><div><strong>${esc(s.name)} · ${esc(s.date)}</strong><div class="${s.net>=0?'good':'bad'}">${sign(s.net)} € netto · ${fmt(s.qty,2)} Stück</div><div class="mini">Vor Steuer ${money(s.gross)} · Steuer ${money(s.tax)} · Haltedauer ${s.durationMin}–${s.durationMax} Tage</div>${effCard(s)}</div><div class="buttons"><button data-sale-del="${esc(s.id)}" class="danger">Stornieren</button></div></div>`).join('')}</div></details>`).join('')}</div></details>`).join('')||'<p class="hint">Noch keine abgeschlossenen Verkäufe.</p>';

$('annualGoal').value=String(settings.goal).replace('.',',');$('defaultTax').value=String(settings.tax).replace('.',',');$('lossStart').value=String(settings.lossStart).replace('.',',');
const months=new Date().getMonth()+1,monthly=yearProfit/months;
$('challengeMetrics').innerHTML=metric('Gewinn dieses Jahr',sign(yearProfit)+' €',yearProfit<0?'bad':'good')+metric('Jahresziel',money(goal))+metric('Ziel erreicht',goal>0?fmt(yearProfit/goal*100,1)+' %':'–')+metric(remain>0?'Noch benötigt':'Über Ziel',money(Math.abs(remain)),remain>0?'':'good')+metric('Ø pro Monat',money(monthly))+metric('Monatliches Soll ab jetzt',money(Math.max(0,remain)/(12-months||1)))+metric('Nettoergebnis gesamt',sign(total.profits+total.interest)+' €');
const map={};for(const s of sales)map[s.date.slice(0,7)]=(map[s.date.slice(0,7)]||0)+s.net;for(const b of bookings)if(b.type==='profit'||b.type==='interest')map[b.date.slice(0,7)]=(map[b.date.slice(0,7)]||0)+b.amount;const firstYear=settings.startYear??2026;const years=[...new Set([firstYear,...Array.from({length:Math.max(4,year-firstYear+2)},(_,i)=>firstYear+i),...Object.keys(settings.yearGoals||{}).map(Number),...sales.map(s=>Number(s.date.slice(0,4))),...bookings.filter(b=>b.type==='profit').map(b=>Number(b.date.slice(0,4)))] )].filter(y=>y>=2000&&y<=2100).sort((a,b)=>a-b);
$('yearGoals').innerHTML='<h3>Individuelle Jahresziele</h3><p class="hint">2026: Oktober–Dezember anteilig. Alle Ziele separat änderbar. Änderungen gelten nur für das gewählte Jahr.</p>'+years.map(y=>`<div class="year-goal"><strong style="min-width:55px">${y}</strong><input data-year-goal="${y}" inputmode="decimal" value="${fmt(yearGoal(y))}" aria-label="Jahresziel ${y}"><span>€ netto</span><button data-year-save="${y}">Speichern</button></div>`).join('');
$('yearResults').innerHTML='<h3>Jahresvergleich</h3><div class="scroll"><table><thead><tr><th>Jahr</th><th>Ziel</th><th>Ergebnis</th><th>Differenz</th></tr></thead><tbody>'+years.map(y=>{const earned=sales.filter(s=>s.date.startsWith(String(y))).reduce((n,s)=>n+s.net,0)+bookings.filter(b=>b.type==='profit'&&b.date.startsWith(String(y))).reduce((n,b)=>n+b.amount,0);return `<tr><td>${y}</td><td>${money(yearGoal(y))}</td><td>${sign(earned)} €</td><td class="${earned>=yearGoal(y)?'good':'bad'}">${sign(earned-yearGoal(y))} €</td></tr>`}).join('')+'</tbody></table></div>';
$('monthlyStats').textContent='Monatsergebnisse: '+(Object.keys(map).sort().reverse().slice(0,12).map(k=>k+': '+sign(map[k])+' €').join(' · ')||'Noch keine Ergebnisse');renderEfficiency();}
$('newTrade').onclick=()=>openBuy();$('tradeCancel').onclick=closeEditors;$('sellCancel').onclick=closeEditors;
$('tradeSave').onclick=()=>{const name=$('tName').value.trim(),date=$('tDate').value,qty=val('tQty'),price=val('tPrice'),fee=val('tFee')??0;if(!name||!date||!(qty>0)||price==null||price<0||fee<0){alert('Bitte gültige Kaufdaten eingeben.');return}let p=tradePosition?positions.find(x=>x.id===tradePosition):positions.find(x=>x.name.toLowerCase()===name.toLowerCase()&&positionQty(x)>0);if(!p){const w=entries.find(x=>x.data.name?.trim().toLowerCase()===name.toLowerCase());p={id:crypto.randomUUID(),name,isin:w?.data.isin||'',wkn:w?.data.wkn||'',lots:[]};positions.push(p)}p.lots.push({id:crypto.randomUUID(),date,qty,remaining:qty,price,fee});if(saveState()){closeEditors();renderTrades();renderWatch();renderCapital()}};
$('positions').addEventListener('input',e=>{const b=e.target.closest('[data-sim]');if(b)updateSimulator(b)});
$('positions').onclick=e=>{const a=e.target.closest('[data-add-lot]'),s=e.target.closest('[data-sell-position]');if(a){const p=positions.find(x=>x.id===a.dataset.addLot);if(p)openBuy(p.name,p.id)}if(s)openSell(s.dataset.sellPosition);const save=e.target.closest('[data-save-plan]');if(save){const p=positions.find(x=>x.id===save.dataset.savePlan);if(!p)return;const box=save.closest('.position-tools');const plan={};for(const input of box.querySelectorAll('[data-plan]')){const v=parse(input.value);if(input.value.trim()&&(v==null||v<0)){alert('Bitte gültige, nichtnegative Werte eingeben.');return}plan[input.dataset.plan]=v}p.plan=plan;saveState();const qty=positionQty(p),cost=p.lots.reduce((n,l)=>n+l.remaining*(l.price+l.fee/l.qty),0),avg=cost/qty;const sellFee=1,rate=Math.max(0,Math.min(100,settings.tax))/100;const target=plan.target??50;const gross=target>=0?target/(1-rate):target;const targetPrice=(cost+sellFee+gross)/qty;const fixed=plan.stop!=null?avg*(1-plan.stop/100):null;const trail=plan.trail!=null&&plan.high!=null?plan.high*(1-plan.trail/100):null;box.querySelector('[data-plan-result]').textContent='Gewinnziel '+money(target)+': rechnerischer Verkaufskurs '+money(targetPrice)+' · Fester Stop '+(fixed==null?'–':money(fixed))+' · Trailing-Stop '+(trail==null?'–':money(trail))+' · Steuer vereinfacht geschätzt; kein garantierter Ausführungskurs.';}};
['sDate','sQty','sPrice','sFee','sTaxMode','sTaxActual'].forEach(id=>$(id).addEventListener('input',previewSale));
$('sellSave').onclick=()=>{const c=saleCalc(),date=$('sDate').value;if(!c||c.invalidTax||!date||c.allocation.some(a=>date<a.date)){alert('Bitte Verkaufsdaten, Steuer und Datum prüfen.');return}const duration=c.allocation.map(a=>Math.round((Date.parse(date)-Date.parse(a.date))/86400000));const s={id:crypto.randomUUID(),positionId:c.p.id,name:c.p.name,date,qty:c.q,price:c.price,fee:c.fee,cost:c.cost,gross:c.gross,tax:c.tax,net:c.net,lossUsed:c.lossUsed,allocation:c.allocation,durationMin:Math.min(...duration),durationMax:Math.max(...duration),taxMode:$('sTaxMode').value};for(const a of c.allocation){const l=c.p.lots.find(x=>x.id===a.lotId);l.remaining=Math.max(0,l.remaining-a.qty)}sales.push(s);if(saveState()){closeEditors();renderTrades();renderCapital()}};
$('sales').onclick=e=>{const b=e.target.closest('[data-sale-del]');if(!b)return;const s=sales.find(x=>x.id===b.dataset.saleDel);if(!s||!confirm('Verkauf stornieren? Zugehörige Stückzahlen werden wiederhergestellt.'))return;const p=positions.find(x=>x.id===s.positionId);if(p)for(const a of s.allocation){const l=p.lots.find(x=>x.id===a.lotId);if(l)l.remaining+=a.qty}sales=sales.filter(x=>x.id!==s.id);saveState();renderTrades();renderCapital()};
$('settingsSave').onclick=()=>{const goal=val('annualGoal'),tax=val('defaultTax'),lossStart=val('lossStart');if(goal==null||goal<0||tax==null||tax<0||tax>100||lossStart==null||lossStart<0){alert('Bitte gültige Werte eingeben.');return}settings={...settings,goal,tax,lossStart};saveState();renderTrades()};

// Move existing position and sales editors without recreating their inputs or changing their data.
const capSections=[...$('capital').querySelectorAll(':scope > section')];$('bought').append(capSections[0],capSections[1]);
$('collapseAll').onclick=()=>document.querySelectorAll('#bookings details,#sales details,#positions details,#watchItems details').forEach(x=>x.open=false);
$('expandAll').onclick=()=>document.querySelectorAll('#bookings details,#sales details,#positions details,#watchItems details').forEach(x=>x.open=true);
// Depot 4.8: vier übersichtliche, zunächst geschlossene Hauptbereiche.
(function buildDepot(){const cap=$('capital');const cards=[...cap.querySelectorAll(':scope > section')];const challenge=cards.find(x=>x.querySelector('#challengeMetrics'));const capitalCard=cards.find(x=>x.querySelector('#capitalMetrics'));const bookingCard=cards.find(x=>x.querySelector('#bookingSave'));const actualCard=cards.find(x=>x.querySelector('#actualTotal'));const historyCard=cards.find(x=>x.querySelector('#bookings'));if(actualCard)actualCard.classList.add('hidden');const wrap=(title,children)=>{const d=document.createElement('details');d.className='fold card';const sum=document.createElement('summary');sum.textContent=title;d.append(sum);const body=document.createElement('div');body.className='fold-body';children.forEach(x=>x&&body.append(x));d.append(body);cap.append(d);return d};const nested=(title,element)=>{const d=document.createElement('details');d.className='fold';const sum=document.createElement('summary');sum.textContent=title;const body=document.createElement('div');body.className='fold-body';body.append(element);d.append(sum,body);return d};const eff=challenge.querySelector('#efficiencyStats').closest('details');const goals=challenge.querySelector('#yearGoals');const goalFold=nested('Jahresziele eingeben',goals);const effFold=wrap('2 · Trade-Effizienz',[eff]);wrap('1 · Mein Kapital',[capitalCard,nested('＋ Buchung hinzufügen',bookingCard)]); // reposition in desired order below
const etf=wrap('3 · ETF-Challenge',[challenge]);challenge.insertBefore(goalFold,challenge.querySelector('#yearResults'));const hist=wrap('4 · Buchungshistorie',[historyCard]);cap.insertBefore(cap.querySelector('details.fold.card:nth-last-of-type(3)'),effFold); // normalize order by title
const all=[...cap.querySelectorAll(':scope > details.fold.card')];all.sort((a,b)=>Number(a.querySelector('summary').textContent[0])-Number(b.querySelector('summary').textContent[0])).forEach(d=>cap.append(d));if(actualCard)cap.append(actualCard);const oldButtons=historyCard.querySelector('#collapseAll')?.parentElement;if(oldButtons){oldButtons.querySelector('#collapseAll').textContent='Alle Unterbereiche schließen';oldButtons.querySelector('#expandAll').textContent='Alle Unterbereiche öffnen'};const add=document.createElement('button');add.textContent='＋ Neues Jahr';add.type='button';add.onclick=()=>{const y=prompt('Für welches Jahr möchtest du ein Ziel hinzufügen?','2030');const n=Number(y);if(!Number.isInteger(n)||n<2000||n>2100)return;settings.yearGoals={...(settings.yearGoals||{}),[n]:yearGoal(n)};saveState();renderTrades();goalFold.open=true};goalFold.querySelector('.fold-body').append(add);
})();
load();reset();bookReset();renderWatch();renderCapital();renderTrades();
